const data = msg.payload;

// Station identification
msg.callsign = data.callsign;
msg.dmrId = data.dmr_id;
msg.hostname = data.hostname;

// PSRAM percentage (working memory) - FREE percentage
msg.psramPercent = ((data.memory.freePsramKB / (data.memory.psramSizeMB * 1024)) * 100).toFixed(1);

// Heap percentage - FREE percentage
msg.heapPercent = data.memory.freeHeapPercent;

// Sketch usage percentage - USED percentage (inverse)
const totalSketch = data.flash.sketchSizeKB + data.flash.freeSketchSpaceKB;
msg.sketchPercent = ((data.flash.freeSketchSpaceKB / totalSketch) * 100).toFixed(1);

// Uptime in human readable format
const uptime = data.uptime;
let uptimeStr = '';
if (uptime.days > 0) uptimeStr += uptime.days + 'd ';
if (uptime.hours > 0) uptimeStr += uptime.hours + 'h ';
uptimeStr += uptime.minutes + 'm ' + uptime.secondsRemaining + 's';
msg.uptimeStr = uptimeStr;
msg.uptimeSeconds = uptime.seconds;

// Chip info
msg.chipModel = data.chip.model;
msg.chipRevision = data.chip.revision;
msg.chipCores = data.chip.cores;
msg.cpuFreq = data.chip.cpuFreqMHz;

// Memory details
msg.freeHeapKB = data.memory.freeHeapKB.toFixed(1);
msg.heapSizeKB = data.memory.heapSizeKB.toFixed(1);
msg.minFreeHeapKB = data.memory.minFreeHeapKB.toFixed(1);
msg.psramSizeMB = data.memory.psramSizeMB;
msg.freePsramKB = data.memory.freePsramKB.toFixed(1);

// Flash info
msg.flashSizeMB = data.flash.sizeMB;
msg.flashSpeedMHz = data.flash.speedMHz;
msg.sketchSizeKB = data.flash.sketchSizeKB.toFixed(1);
msg.freeSketchSpaceKB = data.flash.freeSketchSpaceKB.toFixed(1);

// Firmware version
msg.firmwareVersion = data.firmware.version;
msg.sdkVersion = data.firmware.sdkVersion;
msg.buildDate = data.firmware.buildDate;

return msg;

const data = msg.payload;

msg.modemReady = data.ready;
msg.modemType = data.type;
msg.modemHardware = data.hardware;
msg.modemFirmware = data.firmwareVersion;
msg.modemBuildDate = data.buildDate;
msg.modemCrystal = data.crystal;
msg.modemTransceiver = data.transceiver;
msg.modemAuthor = data.author;
msg.modemGitId = data.gitId;

return msg;

const data = msg.payload;

msg.wifiConnected = data.connected;
msg.wifiApMode = data.apMode;
msg.wifiSSID = data.ssid;
msg.wifiIP = data.ip;
msg.wifiRSSI = data.rssi;
msg.wifiMAC = data.mac;

// Format connection status
if (data.apMode) {
    msg.wifiStatus = `AP Mode: ${data.ssid} (${data.ip})`;
} else if (data.connected) {
    msg.wifiStatus = `${data.ssid} (${data.ip}) - RSSI: ${data.rssi}dBm`;
} else {
    msg.wifiStatus = 'Disconnected';
}

return msg;

const data = msg.payload;

msg.dmrLoggedIn = data.loggedIn;
msg.dmrStatus = data.status;
msg.dmrServer = data.server;
msg.dmrCallsign = data.callsign;
msg.dmrId = data.dmrId;
msg.dmrESSID = data.essid;
msg.dmrTalkgroup = data.currentTalkgroup;
msg.dmrColorCode = data.colorCode;

return msg;

const data = msg.payload;

msg.mmdvmReady = data.ready;
msg.mmdvmRxFreq = data.rxFreq.toFixed(4) + ' MHz';
msg.mmdvmTxFreq = data.txFreq.toFixed(4) + ' MHz';
msg.mmdvmColorCode = data.colorCode;
msg.mmdvmPower = data.power + '%';

return msg;

const data = msg.payload;

msg.stationCallsign = data.callsign;
msg.stationDmrId = data.dmrId;
msg.stationESSID = data.essid;
msg.stationLocation = data.location;
msg.stationIsDefault = data.isDefaultCallsign;

return msg;

const data = msg.payload;

if (data.active) {
    const currentSrcId = data.src_id;
    const lastSrcId = flow.get('slot1_src_id');

    // Check if this is a new transmission (different source or first time)
    if (currentSrcId !== lastSrcId) {
        // Clear any existing timer
        const oldTimer = flow.get('slot1_timer');
        if (oldTimer) {
            clearInterval(oldTimer);
        }

        // Store new transmission info
        flow.set('slot1_src_id', currentSrcId);
        flow.set('slot1_start_time', Date.now());
        flow.set('slot1_callsign', `${data.callsign} (${data.name || 'Unknown'})`);
        flow.set('slot1_location', `${data.city || 'Unknown'}, ${data.country || 'Unknown'}`);
        flow.set('slot1_target', `TG${data.dst_id} (${data.call_type})`);

        // Create new interval timer that updates every second
        const timer = setInterval(() => {
            const startTime = flow.get('slot1_start_time');
            const elapsed = Math.floor((Date.now() - startTime) / 1000);

            node.send({
                slot1Active: true,
                slot1Callsign: flow.get('slot1_callsign'),
                slot1DmrId: flow.get('slot1_src_id'),
                slot1Location: flow.get('slot1_location'),
                slot1Target: flow.get('slot1_target'),
                slot1Duration: `${elapsed}s`
            });
        }, 1000);

        flow.set('slot1_timer', timer);
    }

    // Always update last activity time
    flow.set('slot1_last_activity', Date.now());

    // Send immediate update
    const startTime = flow.get('slot1_start_time');
    const elapsed = Math.floor((Date.now() - startTime) / 1000);

    msg.slot1Active = true;
    msg.slot1Callsign = flow.get('slot1_callsign');
    msg.slot1DmrId = currentSrcId;
    msg.slot1Location = flow.get('slot1_location');
    msg.slot1Target = flow.get('slot1_target');
    msg.slot1Duration = `${elapsed}s`;

} else {
    // Check if we should show idle (10 second timeout)
    const lastActivity = flow.get('slot1_last_activity') || 0;
    if (Date.now() - lastActivity > 10000) {
        // Clear timer and reset state
        const timer = flow.get('slot1_timer');
        if (timer) {
            clearInterval(timer);
            flow.set('slot1_timer', null);
        }

        flow.set('slot1_src_id', null);

        msg.slot1Active = false;
        msg.slot1Callsign = 'Idle';
        msg.slot1DmrId = '-';
        msg.slot1Location = '-';
        msg.slot1Target = '-';
        msg.slot1Duration = '-';
    } else {
        return null; // Don't send update if still active
    }
}

return msg;

