// Send three separate messages for the chart - one for each metric
var psramMsg = { payload: parseFloat(msg.psramPercent), topic: "PSRAM Free" };
var heapMsg = { payload: parseFloat(msg.heapPercent), topic: "Heap Free" };
var sketchMsg = { payload: parseFloat(msg.sketchPercent), topic: "Sketch Free" };

return [psramMsg, heapMsg, sketchMsg];
